import{_ as e,o as s,c as o,a2 as a}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Choosing a model","description":"","frontmatter":{},"headers":[],"relativePath":"models.md","filePath":"models.md","lastUpdated":null}'),n={name:"models.md"};function i(d,t,r,h,l,c){return s(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="choosing-a-model" tabindex="-1">Choosing a model <a class="header-anchor" href="#choosing-a-model" aria-label="Permalink to &quot;Choosing a model&quot;">​</a></h1><p>The <strong>Model</strong> field in the <strong>New session</strong>, <strong>Edit session</strong> and <strong>Duplicate session</strong> dialogs sets the model a session starts on. Below the field the dialog lists the models the selected account offers, with the controls each one has (reasoning effort levels, context size, image input, fast mode) as the agent&#39;s own CLI reports them.</p><p><strong>Edition:</strong> Community · <strong>Who:</strong> the session owner chooses; collaborators can refresh a shared session&#39;s list; viewers of a <a href="/docs/sharing">shared</a> session (Enterprise) only read it.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h2><ol><li>Pick the agent, the billing and, for a subscription, the account.</li><li>Click a model in the list, or type any model id. Leave the field empty to start on the CLI&#39;s default.</li><li><strong>Refresh</strong> asks the agent&#39;s CLI again, through one of your running sessions on the same account.</li></ol><p>Changing the model in <strong>Edit session</strong> takes effect at the session&#39;s next start. Inside a running session the CLI&#39;s own <code>/model</code> command still switches models, as before.</p><h2 id="where-the-list-comes-from" tabindex="-1">Where the list comes from <a class="header-anchor" href="#where-the-list-comes-from" aria-label="Permalink to &quot;Where the list comes from&quot;">​</a></h2><p>AgentHub does not keep its own model list and does not ask the providers itself. The list is what the agent&#39;s CLI reports <strong>inside a session pod, with that session&#39;s login or key</strong>, and it is stored per user and per account:</p><table tabindex="0"><thead><tr><th>Agent</th><th>Source</th><th>Checked against the account?</th></tr></thead><tbody><tr><td>Claude</td><td>Claude Code&#39;s own model list</td><td>Yes for a subscription login (it shapes the list by plan); not for an API key</td></tr><tr><td>Codex</td><td>Codex&#39;s model list</td><td>Yes for a subscription login; not for an API key</td></tr><tr><td>Cursor</td><td><code>agent models</code>, the account&#39;s list</td><td>Yes</td></tr><tr><td>OpenCode</td><td>OpenCode&#39;s models for the providers you are logged in to</td><td>No, it is a catalogue</td></tr><tr><td>Own endpoint</td><td>The endpoint&#39;s <code>/models</code>, asked from the session pod</td><td>Yes, it is the server&#39;s own list</td></tr><tr><td>OpenClaw</td><td>—</td><td>Type the model id; OpenClaw picks its model from the API key</td></tr></tbody></table><p>A running session reports its list shortly after it starts, so the dialog knows an account once any session has run on it.</p><h2 id="what-the-status-line-means" tabindex="-1">What the status line means <a class="header-anchor" href="#what-the-status-line-means" aria-label="Permalink to &quot;What the status line means&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><em>This account&#39;s models</em></td><td>The list came from the provider for this account.</td></tr><tr><td><em>The CLI&#39;s models, not checked against this account</em></td><td>The CLI&#39;s own list; a model the account cannot use fails at the first turn.</td></tr><tr><td><em>No list for this account yet</em></td><td>No session has run on this account. Type an id or leave it empty.</td></tr><tr><td><em>may be out of date</em></td><td>The list is more than a day old. Refresh to update it.</td></tr><tr><td><em>The account&#39;s list was refused</em></td><td>The provider refused this account&#39;s list; the CLI shows its built-in models instead, which the account may not be able to use.</td></tr><tr><td><em>Could not read this account&#39;s models</em></td><td>The CLI is not signed in, the key was refused or the endpoint could not be reached. Type an id instead.</td></tr></tbody></table><p>A model you chose stays chosen even when a later list no longer contains it; the dialog marks it as not listed instead of switching models or accounts for you.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Refresh</strong> needs a running session on the same account. Without one the dialog says so; no pod is started just to read a list.</li><li>For an own endpoint the hub never contacts the endpoint itself. Its list comes from a session pod on that endpoint.</li><li>Cursor&#39;s list was not yet tested against a real Cursor account; if its output cannot be read, the dialog reports an error and the field stays free text.</li><li>Viewers of a shared session see the session&#39;s stored list and chosen model, without any account name, e-mail or key, and cannot refresh it.</li></ul><p>See also <a href="/docs/sessions">Sessions</a> and <a href="/docs/provider-login">Provider login</a>.</p>',16)])])}const p=e(n,[["render",i]]);export{u as __pageData,p as default};
